(x, y, t) => {
  const cx = 240, cy = 120;
  let wx = Math.sin(x*0.018+t*0.3)*18 + Math.cos(y*0.013-t*0.2)*12;
  let wy = Math.cos(y*0.017-t*0.25)*18 + Math.sin(x*0.016+t*0.35)*12;
  wx += Math.sin((x+wx)*0.025+t*0.5)*8 + Math.cos((y+wy)*0.02-t*0.4)*6;
  wy += Math.cos((y+wy)*0.023-t*0.45)*8 + Math.sin((x+wx)*0.019+t*0.55)*6;
  const sx = x+wx, sy = y+wy;
  const src = [
    [160+Math.sin(t*0.6)*100,80+Math.cos(t*0.4)*50,0.08,2.0,0],
    [320+Math.cos(t*0.5)*100,160+Math.sin(t*0.7)*50,0.1,1.7,1],
    [240+Math.sin(t*0.3+2)*140,120+Math.cos(t*0.5+1)*90,0.06,2.3,2],
    [120+Math.cos(t*0.8+1)*80,180+Math.sin(t*0.6+3)*60,0.12,1.5,3],
    [360+Math.sin(t*0.4+4)*90,60+Math.cos(t*0.9+2)*70,0.07,2.6,4],
    [240+Math.cos(t*0.35+5)*120,200+Math.sin(t*0.55)*80,0.09,1.9,5],
    [80+Math.sin(t*0.45+3)*70,40+Math.cos(t*0.65+2)*50,0.11,2.1,1.5],
    [400+Math.cos(t*0.55+1)*60,200+Math.sin(t*0.75+4)*40,0.13,1.6,4.5],
    [200+Math.sin(t*0.38+6)*90,220+Math.cos(t*0.48+3)*70,0.075,2.4,2.8],
    [300+Math.cos(t*0.42+2)*80,100+Math.sin(t*0.62+5)*60,0.095,1.8,3.7]
  ];
  let aS=0, iS=0, fineS=0;
  for(const[sX,sY,f,sp,ph]of src){
    const d=Math.sqrt((sx-sX)**2+(sy-sY)**2);
    aS+=Math.sin(d*f-t*sp+ph);
    iS+=Math.sin(d*f*0.7+t*sp*0.6+ph+1.5);
    fineS+=Math.sin(d*f*2.3-t*sp*1.5+ph*2);
  }
  const act=aS/10, inh=iS/10, fine=fineS/10;
  const bg1=(Math.sin(sx*0.04+sy*0.025+t*0.8)+Math.sin(sx*0.03-sy*0.04+t*1.1))/2;
  const bg2=(Math.sin(sx*0.08-sy*0.06+t*1.6)+Math.cos(sx*0.06+sy*0.07-t*1.3))/2;
  const bg3=Math.sin((sx+sy)*0.12+t*2.5)*0.2+Math.sin((sx-sy)*0.1-t*2)*0.2;
  const bg=bg1+bg2*0.4+bg3;
  const dist=Math.sqrt((sx-cx)**2+(sy-cy)**2), ang=Math.atan2(sy-cy,sx-cx);
  const spiral=(Math.sin(dist*0.05-ang*3-t*1.5)+Math.sin(dist*0.04+ang*4-t*1.2)+Math.sin(dist*0.08-ang*2+t*2)*0.3)*0.35;
  const cell=Math.tanh((Math.sin(sx*0.15)*Math.sin(sy*0.15)+Math.sin((sx+sy)*0.1+t)*0.5+Math.sin(sx*0.22-sy*0.18+t*0.7)*0.3)*1.5)*0.3;
  const r1=Math.tanh((act-inh*0.7+bg*0.25+spiral)*2.2);
  const r2=Math.tanh((fine*0.4-r1*0.3+bg2*0.2)*1.8);
  const reaction=Math.tanh((r1*0.65+r2*0.35+cell*0.2)*1.6);
  const contour=Math.abs(Math.sin(reaction*Math.PI*3))*0.15;
  const v=(reaction*0.7+contour)*0.5+0.5;
  const pal=[[5,10,45],[12,45,85],[18,90,120],[25,140,130],[120,180,90],[220,195,60],[230,140,55],[200,75,60],[150,40,70],[90,25,85],[45,15,65],[15,12,50],[5,10,45]];
  const idx=v*(pal.length-1), i=Math.min(idx|0,pal.length-2), f=idx-i;
  const sf=f*f*(3-2*f);
  const lum=0.85+Math.sin(reaction*Math.PI)*0.15;
  const edge=Math.abs(reaction)>0.65?1.2:Math.abs(reaction)>0.3?1.05:0.95;
  const glow=Math.max(0,reaction)*0.15;
  return[
    Math.min(255,((pal[i][0]+(pal[i+1][0]-pal[i][0])*sf)*lum*edge+glow*80)|0),
    Math.min(255,((pal[i][1]+(pal[i+1][1]-pal[i][1])*sf)*lum*edge+glow*40)|0),
    Math.min(255,((pal[i][2]+(pal[i+1][2]-pal[i][2])*sf)*lum*edge+glow*30)|0)
  ];
}
